export function parseDate(key){const [y,m,d]=key.split('-').map(Number);return new Date(Date.UTC(y,m-1,d));}
export function dateKey(date){return date.toISOString().slice(0,10);}
export function monthDays(year,month){const first=new Date(Date.UTC(year,month,1));const count=new Date(Date.UTC(year,month+1,0)).getUTCDate();const cells=Array(first.getUTCDay()).fill(null);for(let day=1;day<=count;day++)cells.push(dateKey(new Date(Date.UTC(year,month,day))));while(cells.length%7)cells.push(null);return cells;}
export function shiftMonth(year,month,amount){const d=new Date(Date.UTC(year,month+amount,1));return {year:d.getUTCFullYear(),month:d.getUTCMonth()};}
export function jstToday(date=new Date()){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const v=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${v.year}-${v.month}-${v.day}`;}
export function dayDiff(target,today=jstToday()){return Math.round((parseDate(target)-parseDate(today))/86400000);}
export function eventsFor(events,{month=null,date=null,type='all',query='',exam=null}={}){const q=query.trim().toLocaleLowerCase('ja');return events.filter(e=>(!month||e.date.startsWith(month))&&(!date||e.date===date)&&(type==='all'||e.type===type)&&(!exam||e.exam===exam)&&(!q||`${e.name} ${e.aliases||''} ${e.edition||''}`.toLocaleLowerCase('ja').includes(q))).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));}
export function readSaved(storage){try{const s=JSON.parse(storage.getItem('michi-v1')||'{}');return {saved:Array.isArray(s.saved)?s.saved.filter(x=>typeof x==='string'):[],applied:Array.isArray(s.applied)?s.applied.filter(x=>typeof x==='string'):[],checks:s.checks&&typeof s.checks==='object'&&!Array.isArray(s.checks)?s.checks:{}};}catch{return {saved:[],applied:[],checks:{}};}}
